import json
with open('json/circuits.json') as f:
    data = json.load(f)
records = data['records']
circuits_by_id = {r['circuitId']: r for r in records}
print(f"Total circuits: {len(records)}")

# Get distinct circuit IDs in European GP races
circuit_ids = [12, 20, 26, 31, 38, 73]
for cid in circuit_ids:
    if cid in circuits_by_id:
        print(f"circuitId={cid}: {circuits_by_id[cid]['name']} ({circuits_by_id[cid]['country']})")
    else:
        print(f"circuitId={cid}: NOT FOUND")
